  function armScratch() {
    var fired = false;
    var delayMs = Math.max(1, parseInt(CFG.scratchDelay, 10) || 12) * 1000;

    function fire(reason) {
      if (fired) return;
      fired = true;
      try {
        if (sessionStorage.getItem("gh_scratch_seen") === "1") return;
        sessionStorage.setItem("gh_scratch_seen", "1");
      } catch (e) {}
      beacon("scratch_trigger", { reason: reason });
      scratchCard();
    }

    setTimeout(function () { fire("hesitation_" + (delayMs / 1000) + "s"); }, delayMs);

    D.addEventListener("mouseout", function (e) {
      if (!e.relatedTarget && e.clientY <= 0) fire("exit_intent");
    });
    D.addEventListener("visibilitychange", function () {
      if (D.visibilityState === "hidden") fire("tab_blur");
    });
  }

