  /* ================= 5. purchase click tracking ================= */
  function trackPurchaseClicks() {
    D.addEventListener("click", function (e) {
      var t = e.target;
      if (!t || !t.closest) return;
      var btn = t.closest('button, a, input[type="submit"]');
      if (!btn) return;
      var txt = (btn.textContent || btn.value || "").toLowerCase();
      if (/checkout|buy\s*now|add\s*to\s*cart|purchase|order\s*now/.test(txt)) {
        beacon("purchase_click", { text: txt.slice(0, 60) });
      }
    }, true);
  }

